entries[7560] = { ["name"] = "Bauplan: Gnomenuniversalfernbedienung", ["text"] = "Benötigt Ingenieurskunst (125)\nBenutzen: Lehrt Euch die Herstellung einer Gnomenuniversalfernbedienung.\nVerkaufspreis:\nGnomenuniversalfernbedienung\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst (125)\nBenutzen: Ermöglicht für kurze Zeit die Kontrolle eines mechanischen Ziels. Manchmal funktioniert das allerdings nicht und lässt die Maschine einfach erstarren oder macht sie sehr, sehr ärgerlich. Gnomeningenieurskunst vom Feinsten. (3 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Bronzebarren (6), Surrendes bronzenes Dingsda , Fläschchen Öl (2), Tigerauge , Malachit" }
entries[7561] = { ["name"] = "Bauplan: Goblinüberbrückungskabel", ["text"] = "Benötigt Ingenieurskunst (165)\nBenutzen: Lehrt Euch die Herstellung der Goblinüberbrückungskabel.\nVerkaufspreis:\nGoblinüberbrückungskabel\nBenötigt Ingenieurskunst (165)\nBenutzen: Mit Überbrückungskabeln kann man manchmal einen toten Verbündeten ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Eisenbarren (6), Surrendes bronzenes Dingsda (2), Fläschchen Öl (2), Seidenstoff (2), Schattenedelstein (2), Verschmorte Verkabelung" }
