entries[8780] = { ["name"] = "Buch des Sternenfeuers V", ["text"] = "Klassen: Mönch , Druide\nBenötigt Stufe 50\nBenutzen: Lehrt 'Mondfeuer' (Rang 5).\nÜberzieht einen Gegner mit 1 Arkanschaden und im Verlauf von 14 Sek. zusätzlich 176 Arkanschaden. [ Finsternis : Eure kritischen Treffer mit 'Sternenfeuer' und 'Sternensog' gegen das Ziel verlängern die Dauer Eures Zaubers 'Mondfeuer' um 2 Sek ]\nVerkaufspreis:" }
entries[8781] = { ["name"] = "Buch des Nachwachsens VII", ["text"] = "Klassen: Mönch , Druide\nBenötigt Stufe 48\nBenutzen: Lehrt 'Verjüngung' (Rang 1).\nHeilt ein verbündetes Ziel um 945 sowie zusätzlich im Verlauf von 6 Sek. um weitere 3 .\n\n'Nachwachsen' hat eine [ Glyphe 'Nachwachsen' : 100 / 60]% höhere Chance, einen kritischen Effekt zu erzielen.\n\nDie Dauer des Heileffekts wird automatisch auf 6 Sek. zurückgesetzt, wenn 'Nachwachsen' Ziele mit 50% oder weniger Gesundheit heilt. [ Inkarnation : Baum des Lebens: Spontanzauber. ]\nVerkaufspreis:" }
