entries[8786] = { ["name"] = "Buch der Gelassenheit III", ["text"] = "Klassen: Mönch , Druide\nBenötigt Stufe 50\nBenutzen: Lehrt 'Gelassenheit' (Rang 1).\nHeilt die 5 (12 in 25 - Spieler - Instanzen) Gruppen- oder Schlachtzugsmitglieder innerhalb von 40 Metern, deren Gesundheit am niedrigsten ist, 8 Sek. lang alle 2 Sek. um 864 Gesundheit.\n\nZusätzlich heilt 'Gelassenheit' 8 Sek. lang alle 2 Sek. um 1 Gesundheit. Bis zu 3-mal stapelbar. Der Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten.\nVerkaufspreis:" }
